class WorkStepRequest(_WorkStepRequestRequired, total=False):
    """Record a step of the leased work (fenced by workerId, lockVersion, attemptId). INTENT first, then the outcome; an identical repeat is a no-op, an outcome for a step already SUCCEEDED is 409 STEP_ALREADY_RECORDED.

Schema ``WorkStepRequest``."""
    result: Any
    providerRef: str
    error: str


class _WorkUnlockRequestRequired(TypedDict):
    workerId: str
    lockVersion: int


class WorkUnlockRequest(_WorkUnlockRequestRequired, total=False):
    """Explicit release (LOCKED → AVAILABLE).

Schema ``WorkUnlockRequest``."""
    attemptId: str


class WorkerInfo(TypedDict, total=False):
    """Worker seen by the server (R26).

Schema ``WorkerInfo``."""
    workerId: str
    sdk: str
    sdkVersion: str
    language: str
    topics: list[str]
    activeLeases: int
    heartbeatAgeSec: int
    errorRate: Number
    staleLeaseCount: int
